package com.bank.dsa;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.logging.*;

// Runnable demo: add two deposit amounts into one daily total.
public class DepositDemo {
    private static final Logger log = Logger.getLogger(DepositDemo.class.getName());

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        Logger root = Logger.getLogger("");
        for (Handler old : root.getHandlers()) root.removeHandler(old);
        root.addHandler(h);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        DepositTotalService service = new DepositTotalService();

        // Amounts built from String form -> exact decimal (never from double).
        BigDecimal morning   = new BigDecimal("4000.00");  // A
        BigDecimal afternoon = new BigDecimal("7000.00");  // B
        BigDecimal total = service.addAmounts(morning, afternoon);  // sum = A + B

        log.info(() -> "Rajesh SAV2001 daily deposit total = Rs." + total);
    }
}

// ─── Would be in DepositTotalService.java in a real project ───
class DepositTotalService {
    // sum = A + B, kept exact to two decimal places (paisa).
    BigDecimal addAmounts(BigDecimal a, BigDecimal b) {
        if (a == null || b == null) {
            throw new IllegalArgumentException("Amounts must not be null");
        }
        if (a.signum() < 0 || b.signum() < 0) {
            throw new IllegalArgumentException("Deposit amounts must be non-negative");
        }
        return a.add(b).setScale(2, RoundingMode.HALF_EVEN);  // BigDecimal add, fixed scale
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
